"""Measure independent school schedule and physical beacon facts without a legal verdict."""

from __future__ import annotations

from datetime import datetime, timedelta


HASH_FIELDS = (
    "calendar_source_sha256", "operation_schedule_source_sha256",
    "class_schedule_source_sha256", "local_clock_source_sha256",
    "beacon_configuration_source_sha256", "beacon_state_source_sha256",
    "sign_instruction_source_sha256", "zone_designation_source_sha256",
)


def instant(value: object, label: str) -> datetime:
    if not isinstance(value, str):
        raise ValueError("original offset-aware " + label + " required")
    try:
        dt = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError("valid " + label + " required") from exc
    if dt.tzinfo is None or dt.utcoffset() is None:
        raise ValueError("offset-aware " + label + " required")
    return dt


def derive(packet: dict) -> dict:
    if not isinstance(packet, dict) or packet.get("source_kind") != "original_school_schedule_and_device_readback":
        raise ValueError("original school schedule and device readback required")
    for name in HASH_FIELDS:
        value = packet.get(name)
        if not isinstance(value, str) or len(value) != 64 or any(char not in "0123456789abcdef" for char in value):
            raise ValueError("independent source hash required: " + name)
    now = instant(packet.get("local_datetime"), "local clock")
    end = instant(packet.get("last_operation_end"), "last operation end")
    start = instant(packet.get("next_operation_start"), "next operation start")
    class_start = instant(packet.get("class_start"), "class start")
    class_end = instant(packet.get("class_end"), "class end")
    if not end < start or not class_start < class_end:
        raise ValueError("school schedule ordering invalid")
    for name in ("school_in_session", "beacon_operational", "sign_limit_active",
                 "zone_designated_by_operational_beacon"):
        if type(packet.get(name)) is not bool:
            raise ValueError("original school/device fact required: " + name)
    count = packet.get("beacon_yellow_light_count")
    if type(count) is not int or count < 0:
        raise ValueError("original beacon yellow-light count required")
    if type(packet.get("beacon_alternating_flash_capable")) is not bool:
        raise ValueError("original beacon alternating capability required")
    if packet["zone_designated_by_operational_beacon"]:
        if not packet["beacon_operational"] or count < 2 or not packet["beacon_alternating_flash_capable"]:
            raise ValueError("operational speed-limit beacon definition not demonstrated")
    lights = packet.get("lamp_state_samples")
    if not isinstance(lights, list) or len(lights) < 4:
        raise ValueError("synchronized original lamp-state samples required")
    for row in lights:
        if not isinstance(row, dict) or type(row.get("original_frame")) is not int:
            raise ValueError("original lamp frame required")
        states = row.get("yellow_lamps_on")
        if not isinstance(states, list) or len(states) != count or any(type(state) is not bool for state in states):
            raise ValueError("all original yellow lamp states required")
    frames = [row["original_frame"] for row in lights]
    if frames != sorted(set(frames)):
        raise ValueError("lamp samples must retain unique original frame order")
    alternating_observed = any(
        left["yellow_lamps_on"][i] and right["yellow_lamps_on"][j]
        and not left["yellow_lamps_on"][j] and not right["yellow_lamps_on"][i]
        for left, right in zip(lights, lights[1:])
        for i in range(count) for j in range(count) if i != j
    )
    if alternating_observed and not packet["beacon_operational"]:
        raise ValueError("nonoperational beacon cannot have original alternating indication")
    after_end_min = (now - end).total_seconds() / 60
    before_start_min = (start - now).total_seconds() / 60
    # Equality is a measured boundary. Its legal treatment stays unresolved.
    between_operation = end + timedelta(minutes=30) < now < start - timedelta(minutes=30)
    boundary = now == end + timedelta(minutes=30) or now == start - timedelta(minutes=30)
    return {
        "school_in_session": packet["school_in_session"],
        "after_end_minutes": after_end_min,
        "before_start_minutes": before_start_min,
        "between_operation_interior": between_operation,
        "half_hour_boundary": boundary,
        "during_pupil_class_hours": class_start <= now <= class_end,
        "zone_designated_by_operational_beacon": packet["zone_designated_by_operational_beacon"],
        "beacon_operational": packet["beacon_operational"],
        "beacon_yellow_light_count": count,
        "alternating_flash_observed": alternating_observed,
        "sign_limit_active": packet["sign_limit_active"],
        "legal_judgment": None,
        "source_limit": "Source clock and device states are measurements; original zone governance and statutory exception need independent review.",
    }

"""Resolve reviewed original site bytes before a Native school-zone pass."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from school_pass import SOURCES, construct as construct_pass, validate_scene
from school_timing import HASH_FIELDS


TIMING_SOURCE = {
    "calendar_source_sha256": "school_calendar",
    "operation_schedule_source_sha256": "operation_schedule",
    "class_schedule_source_sha256": "class_schedule",
    "local_clock_source_sha256": "local_clock",
    "beacon_configuration_source_sha256": "beacon_configuration",
    "beacon_state_source_sha256": "beacon_state",
    "sign_instruction_source_sha256": "sign_instruction",
    "zone_designation_source_sha256": "zone_designation",
}


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def validate_site(path: Path, case_id: str) -> dict:
    path = Path(path).resolve()
    site = json.loads(path.read_text())
    records = site.get("source_records")
    if not isinstance(records, dict) or set(records) != set(SOURCES):
        raise ValueError("reviewed original school-zone source inventory incomplete")
    for name in SOURCES:
        row = records[name]
        if not isinstance(row, dict) or not isinstance(row.get("path"), str):
            raise ValueError("reviewed source path missing: " + name)
        source = (path.parent / row["path"]).resolve()
        if path.parent not in source.parents or not source.is_file():
            raise ValueError("reviewed source outside original site packet: " + name)
        digest = sha(source)
        if digest != row.get("sha256") or digest != site.get(name + "_source_sha256"):
            raise ValueError("original school-zone source hash differs: " + name)
    timing = site.get("timing_packet", {})
    for field in HASH_FIELDS:
        if timing.get(field) != records[TIMING_SOURCE[field]]["sha256"]:
            raise ValueError("independent school timing/device source differs: " + field)
    if site.get("map_sha256") != records["map_geometry"]["sha256"]:
        raise ValueError("physical map source hash differs")
    validate_scene(site, case_id)
    site["_source_sha256"] = sha(path)
    return site


def construct(adapter, site_path: Path, case_id: str) -> dict:
    site = validate_site(site_path, case_id)
    return construct_pass(adapter, site, case_id)

"""CPU fake of one full original Native episode and restoration path."""

from __future__ import annotations

import io
import json
import os
from pathlib import Path
import sys
import tempfile
import types
import unittest
from unittest.mock import patch

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import native_capture
from test_school_pass import rows, scene


class FakeWorld:
    def __init__(self):
        self.settings = types.SimpleNamespace(synchronous_mode=False, fixed_delta_seconds=None)
        self.frame = 9999

    def get_settings(self):
        return self.settings

    def apply_settings(self, value):
        self.settings = value

    def tick(self):
        self.frame += 1
        return self.frame

    def get_snapshot(self):
        return types.SimpleNamespace(frame=self.frame,
                                     timestamp=types.SimpleNamespace(elapsed_seconds=1 + (self.frame - 10000) / 20))


class FakeEncoder:
    def __init__(self, path):
        path.write_bytes(b"fake camera bytes for code-path test")
        self.stdin = io.BytesIO()
        self.stderr = io.BytesIO()

    def wait(self, timeout=None):
        return 0

    def poll(self):
        return 0


class FakeAdapter:
    def __init__(self, site):
        self.site = site
        self.original = rows(site)
        self.calls = []

    def read_original_context(self, site, case_id):
        return dict(site)

    def control_frame(self, case_id, index):
        self.calls.append((case_id, index))

    def read_original_frame(self, case_id, index, frame):
        row = dict(self.original[index])
        row.update(native_frame=frame, frame=index, time_s=index / 20,
                   ego_actor_id=1, target_actor_id=2,
                   ego_vehicle_blueprint="vehicle.tesla.model3",
                   target_vehicle_blueprint="vehicle.audi.a2",
                   ego_body_vertices_m=[[0, 0, 0]] * 4,
                   target_body_vertices_m=[[1, 0, 0]] * 4)
        return row

    def camera_rgb24(self, view, frame):
        return b"\x01\x02\x03"


class FakePipelineCapture:
    calls = []

    def __init__(self, client, ego, output, case_id):
        self.case_id = case_id
        self.calls.append(("init", case_id))

    def __enter__(self):
        return self

    def capture(self, frame, elapsed):
        self.calls.append((frame, elapsed))

    def __exit__(self, kind, value, traceback):
        self.calls.append(("close", kind))


class NativeCaptureTests(unittest.TestCase):
    def test_exact_original_frames_four_cameras_and_world_restore(self):
        scratch = Path(os.environ["TMPDIR"])
        with tempfile.TemporaryDirectory(dir=scratch) as directory:
            output = Path(directory)
            site = scene()
            site["_source_sha256"] = "a" * 64
            site["map_sha256"] = "b" * 64
            adapter = FakeAdapter(site)
            world = FakeWorld()
            module = types.ModuleType("pipeline_capture")
            module.PipelineCapture = FakePipelineCapture
            FakePipelineCapture.calls = []
            def encode(root, view):
                return FakeEncoder(root / (view + ".mkv"))
            with patch.dict(sys.modules, {"pipeline_capture": module}), \
                 patch.object(native_capture, "SIZES", {view: (1, 1) for view in native_capture.VIEWS}), \
                 patch.object(native_capture, "encoder", encode):
                result = native_capture.capture(object(), world, adapter, object(), site,
                                                site["case_id"], output, site["_source_sha256"])
            self.assertEqual(len(adapter.calls), 900)
            self.assertEqual(len([x for x in FakePipelineCapture.calls if type(x[0]) is int]), 900)
            self.assertEqual(json.loads(Path(result["receipt"]).read_text())["frame_count"], 900)
            self.assertFalse(world.get_settings().synchronous_mode)
            self.assertIsNone(world.get_settings().fixed_delta_seconds)
            self.assertEqual(len(Path(result["trace"]).read_text().splitlines()), 900)

    def test_missing_second_vehicle_readback_rejected(self):
        row = {"native_frame": 4, "original_frame": 4, "frame": 0, "time_s": 0}
        with self.assertRaisesRegex(ValueError, "two-vehicle readback missing"):
            native_capture.validate_frame(row, 0, 4, 1.0)


if __name__ == "__main__":
    unittest.main()
